fast_pseudocode:
# After: more configs, tl.full mask (SLOWER)
@triton.autotune(configs=[
    Config({'XBLOCK': 16, 'YBLOCK': 32},  num_warps=2),
    Config({'XBLOCK': 32, 'YBLOCK': 32},  num_warps=4),
    ...  # 10 configs total
], key=['ynumel', 'xnumel'])
def kernel(...):
    ymask = tl.full([YBLOCK], True, tl.int1)[:, None]  # always-true mask
    tmp0 = tl.load(ptr + offset, mask=xmask & ymask)
    tl.store(out + offset, tmp0, mask=xmask & ymask)
